toolUseResult.originalFile:
"""The forecasting seam, and the only adapter that currently exists.

No engine has been selected or evaluated for this project. Rather than leave a
gap where someone later drops in a plausible-looking curve, the default adapter
is a placeholder that returns a *status*. Two spec rules are enforced here in
code rather than in prose:

* An unsupported output is unavailable, never zero.
* Nothing emits a fatigue or effectiveness number under the FAST name without
  an adapter that has declared, and had recorded, its own evidence.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Protocol

from .opportunity import OpportunityReport

__all__ = ["Capabilities", "ModelAdapter", "ModelResult", "UnevaluatedAdapter", "get_adapter"]


@dataclass(frozen=True)
class Capabilities:
    """What an adapter claims it can do. Claims still require evidence."""

    outputs: tuple[str, ...]
    supports_travel: bool
    requires_sleep_history: bool
    evidence: str


@dataclass(frozen=True)
class ModelResult:
    """A forecast, or a documented reason there isn't one."""

    adapter_name: str
    adapter_version: str
    available: bool
    reason: str
    generated_at: datetime
    series: dict[str, list[float]] | None = None
    summaries: dict[str, float] | None = None

    def summary(self, name: str) -> float | None:
        """A requested summary, or ``None`` when unsupported. Never ``0.0``."""
        if not self.available or self.summaries is None:
            return None
        return self.summaries.get(name)


class ModelAdapter(Protocol):
    name: str
    version: str

    def capabilities(self) -> Capabilities: ...
    def validate(self, report: OpportunityReport) -> list[str]: ...
    def simulate(self, report: OpportunityReport, *, requires_travel: bool = False) -> ModelResult: ...


class UnevaluatedAdapter:
    """The default: reports that no engine has been selected or evaluated."""

    name = "unevaluated"
    version = "0.1.0"

    def capabilities(self) -> Capabilities:
        return Capabilities(
            outputs=(),
            supports_travel=False,
            requires_sleep_history=False,
            evidence=(
                "None. No engine selected; SAFTE-FAST licensing and SAFTEr suitability "
                "both remain open questions in FAST-MODERNIZATION-RESEARCH.md."
            ),
        )

    def validate(self, report: OpportunityReport) -> list[str]:
        warnings = [
            "No forecasting engine has been evaluated for this population; "
            "opportunity figures carry no fatigue or effectiveness interpretation.",
        ]
        if report.conflicts:
            warnings.append(
                f"{len(report.conflicts)} scheduling conflict(s) remain unresolved in this scenario."
            )
        return warnings

    def simulate(
        self, report: OpportunityReport, *, requires_travel: bool = False
    ) -> ModelResult:
        reason = (
            "Unavailable: no forecasting engine has been selected or evaluated for "
            "this project, so no effectiveness or fatigue value can be produced."
        )
        if requires_travel:
            reason += (
                " This scenario also requires transmeridian travel support, which "
                "this adapter does not provide."
            )
        return ModelResult(
            adapter_name=self.name,
            adapter_version=self.version,
            available=False,
            reason=reason,
            generated_at=datetime.now(timezone.utc),
        )


_ADAPTERS: dict[str, type] = {"unevaluated": UnevaluatedAdapter}


def get_adapter(name: str = "unevaluated") -> ModelAdapter:
    """Look up an adapter. Unknown names fail loudly rather than degrade."""
    try:
        return _ADAPTERS[name]()
    except KeyError:
        raise KeyError(
            f"no adapter registered as {name!r}; available: {sorted(_ADAPTERS)}"
        ) from None

