"""Opportunity calculation from SLEEP-SCHEDULER-SPEC.md.

The rule these tests defend: free time is not opportunity. A window only counts
because staff entered it, and it only counts for the part that survives the
mandatory obligations and their transitions.
"""

from datetime import timedelta

import pytest

from sleep_scheduler.opportunity import compare, evaluate
from sleep_scheduler.schedule import (
    AssumptionSet,
    Event,
    ProtectedSleepWindow,
    Scenario,
)
from sleep_scheduler.temporal import Interval

CHICAGO = "America/Chicago"

NO_TRANSITIONS = AssumptionSet(
    sleep_target_hours=8.0,
    pre_bed_minutes=0,
    morning_minutes=0,
    source="test fixture",
)

OVERNIGHT = Interval.of("2026-09-12T18:00", "2026-09-13T12:00", CHICAGO)


def window(start: str, end: str, id: str = "w1", kind: str = "hotel"):
    return ProtectedSleepWindow(
        id=id, label=id, interval=Interval.of(start, end, CHICAGO), kind=kind
    )


def event(start: str, end: str, id: str = "e1", kind: str = "treatment"):
    return Event(
        id=id, kind=kind, title=id, interval=Interval.of(start, end, CHICAGO)
    )


def scenario(windows, events=(), assumptions=NO_TRANSITIONS):
    return Scenario(
        id="s1",
        title="test",
        display_zone=CHICAGO,
        events=list(events),
        windows=list(windows),
        assumptions=assumptions,
    )


def test_entered_window_with_no_obligations_yields_its_full_duration():
    report = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:00")]), OVERNIGHT)
    assert report.hours == 6.5


def test_extending_the_window_by_thirty_minutes_adds_half_an_hour():
    # Spec acceptance row: 6.5 vs 7.0 hours opportunity, +30 minutes.
    baseline = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:00")]), OVERNIGHT)
    candidate = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:30")]), OVERNIGHT)
    delta = compare(baseline, candidate)
    assert (baseline.hours, candidate.hours) == (6.5, 7.0)
    assert delta.hours_delta == 0.5


def test_report_states_opportunity_and_never_claims_sleep_obtained():
    report = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:00")]), OVERNIGHT)
    assert report.measure == "sleep opportunity"
    assert not hasattr(report, "sleep_hours")
    assert not hasattr(report, "predicted_sleep_hours")


def test_free_afternoon_time_is_not_counted_as_opportunity():
    # Nothing scheduled all afternoon, but no window was entered for it.
    report = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:00")]), OVERNIGHT)
    assert report.hours == 6.5


def test_two_overlapping_windows_are_counted_once():
    report = evaluate(
        scenario(
            [
                window("2026-09-12T22:00", "2026-09-13T04:00", id="w1"),
                window("2026-09-13T03:00", "2026-09-13T06:00", id="w2"),
            ]
        ),
        OVERNIGHT,
    )
    assert report.hours == 8.0


def test_overlapping_windows_retain_their_source_intervals():
    report = evaluate(
        scenario(
            [
                window("2026-09-12T22:00", "2026-09-13T04:00", id="w1"),
                window("2026-09-13T03:00", "2026-09-13T06:00", id="w2"),
            ]
        ),
        OVERNIGHT,
    )
    assert [w.id for w in report.sources] == ["w1", "w2"]


def test_nap_overlapping_another_opportunity_is_not_double_counted():
    report = evaluate(
        scenario(
            [
                window("2026-09-13T13:00", "2026-09-13T15:00", id="w1"),
                window("2026-09-13T14:00", "2026-09-13T15:30", id="nap", kind="nap"),
            ]
        ),
        Interval.of("2026-09-13T12:00", "2026-09-13T18:00", CHICAGO),
    )
    assert report.hours == 2.5


def test_nap_label_is_preserved_alongside_the_merged_total():
    report = evaluate(
        scenario(
            [
                window("2026-09-13T13:00", "2026-09-13T15:00", id="w1"),
                window("2026-09-13T14:00", "2026-09-13T15:30", id="nap", kind="nap"),
            ]
